// Private, affine one-fixture request. No Clone/Copy, retry, public mint,
// environment/argv constructor, allocation/leak, or borrowed-output escape.
struct OneFixtureOuterRequestV1<'p0> {
    preexisting: &'p0 PreexistingImmutableBindingV1<'p0>,
}
enum BindingSelectionRefusalV1 { ImmutableBindingAndP0ReviewPending }
fn selected_outer_request_v1<'p0>()
    -> Result<OneFixtureOuterRequestV1<'p0>, BindingSelectionRefusalV1>
{
    // Changing this exact source requires actual immutable identity, full
    // binding/native backing layout, source work and root P0 funding review.
    // The selected source/limits above are constraints, not a fabricated
    // fresh validation, executable, session, path or completed authority.
    Err(BindingSelectionRefusalV1::ImmutableBindingAndP0ReviewPending)
}

enum AdmittedOuterResultV1 {
    BootstrapRefused(super::BootstrapFailureV1),
    AccountRefused(RefusalV1), EntryRefused(RefusalV1),
    Returned { original_observation:OriginalObservationV1,retirement:RetirementObservationV1 },
}
fn consume_admitted_owner_once_v1(owner: super::AdmittedImmutableOwnerV1<'_>)
    -> AdmittedOuterResultV1
{
    let attempt_result = {
        let data = owner.scoped_binding_v1();
        let [source,build,session,executable,compiler,compiler_version,compile_manifest,
            compile_argv,compile_environment,process_argv,process_environment,review] = data.identities
            .map(|(bytes,sha256)| ImmutableIdentityPreimageV1 { bytes,sha256 });
        let preexisting = PreexistingImmutableBindingV1 {
            binding: ReviewedFixtureBindingV1 { paths:data.paths,claims:super::copy_claims_v1(data.claims),
                original_validation_budget:data.validation,product_budget:data.product },
            native_path_bodies:data.retained_paths,
            identities:ImmutableFixtureIdentitiesV1 { source,build,session,executable,compiler,compiler_version,
                compile_manifest,compile_argv,compile_environment,process_argv,process_environment,review },
        };
        match owner.correlation_scope_v1() {
            Err(original) => AdmittedOuterResultV1::BootstrapRefused(original),
            Ok((expected,attempt)) => match host_account_v1::selected_parent_account_v1() {
                Err(original) => AdmittedOuterResultV1::AccountRefused(original),
                Ok(account) => {
                    let fixture = FrozenFixtureV1 { binding:&preexisting.binding };
                    match super::run_one_admitted_fixture_v1(&account,fixture,attempt,&expected) {
                        Err(original) => AdmittedOuterResultV1::EntryRefused(original),
                        Ok(owned_child) => {
                            let original_observation = observe_admitted_originals_v1(&owned_child);
                            let retirement = match super::destroy_returned_admitted_fixture_v1(owned_child) {
                                Some(original_token) => { release_after_retirement_v1(original_token);

    // Every binding/correspondence/result view above ended. The acquired
    // owner and separate cleanup partition still live until this consume.
    // Child destruction does not discharge acquisition correlation. The
    // shared owner core permanently retains that charge after scope issue;
    // a reviewed joint-retirement protocol and new prices remain Pending.
    crate::experimental_swift_reactor::retained_profile_loader_v1::retire_admitted_owner_v1(owner);
    attempt_result
}

